// 18-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    reg  [15:0] p  [0:17];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 + 3 * x;
            p[1] <= 16'd2 * xs[1] + 8'd5 + 3 * xs[0];
            p[2] <= 16'd2 * xs[2] + 8'd9 + 3 * xs[1];
            p[3] <= 16'd2 * xs[3] + 8'd13 + 3 * xs[2];
            p[4] <= 16'd2 * xs[4] + 8'd17 + 3 * xs[3];
            p[5] <= 16'd2 * xs[5] + 8'd21 + 3 * xs[4];
            p[6] <= 16'd2 * xs[6] + 8'd25 + 3 * xs[5];
            p[7] <= 16'd2 * xs[7] + 8'd29 + 3 * xs[6];
            p[8] <= 16'd2 * xs[8] + 8'd33 + 3 * xs[7];
            p[9] <= 16'd2 * xs[9] + 8'd37 + 3 * xs[8];
            p[10] <= 16'd2 * xs[10] + 8'd41 + 3 * xs[9];
            p[11] <= 16'd2 * xs[11] + 8'd45 + 3 * xs[10];
            p[12] <= 16'd2 * xs[12] + 8'd49 + 3 * xs[11];
            p[13] <= 16'd2 * xs[13] + 8'd53 + 3 * xs[12];
            p[14] <= 16'd2 * xs[14] + 8'd57 + 3 * xs[13];
            p[15] <= 16'd2 * xs[15] + 8'd61 + 3 * xs[14];
            p[16] <= 16'd2 * xs[16] + 8'd65 + 3 * xs[15];
            p[17] <= 16'd2 * xs[17] + 8'd69 + 3 * xs[16];
            y <= p[17];
        end
    end
endmodule
